//                          Wirkung des Schluessels
//     Eine Stufe ist geschafft, wenn ALLE Tests mit diesem Anfang gruen
//     sind. Fuer MeineChiffre muessen ALLE Tests gruen sein.
//
//  4. MeineChiffre: Trage oben in der Klasse ein
//       - NAME eures Verfahrens,
//       - das Beispiel aus dem Baukasten (Klartext, Schluessel und den
//         Geheimtext, den der Baukasten dafuer anzeigt),
//       - zwei verschiedene gueltige Schluessel fuer die Tests.
//     Euer Schluessel ist EINE Zeichenkette. Braucht ihr mehrere
//     Teilschluessel (z. B. Zahl fuer Caesar und Wort fuer Vigenere),
//     legt ihr selbst ein Format fest, z. B. "7-LUNA", und zerlegt ihn
//     mit charAt/substring. Schreibt das Format in den Kommentar!
//
//  5. Die Testklassen darfst du NICHT veraendern.
//
//  SPIELREGELN (wie im Abitur):
//  - Zeichenketten nur mit length(), charAt(i), substring(a, b), +,
//    equals(...), contains(...), compareTo(...); Zeichen <-> Zahl mit
//    (int) c und (char) n. NICHT erlaubt: toUpperCase, split, indexOf,
//    replace ... Zeichenketten IMMER mit equals vergleichen.
//  - Im Programm gilt A = 0 ... Z = 25 (ASCII-Wert - 65), auf Papier und
//    in der Abitur-Anlage A = 1 ... Z = 26 (Falle P1).
//  - In Java ist -3 % 26 = -3. Benutze Hilfe.mod (Falle P2).
//  - Alle Bausteine arbeiten auf normalisiertem Text (nur A-Z). Es wird
//    NIE mit X aufgefuellt: unvollstaendige Spalten/Bloecke bleiben
//    unvollstaendig (Falle P4).
// =====================================================================


// ---------------------------------------------------------------------
//  GERÜST – hier nichts veraendern
// ---------------------------------------------------------------------

class Hilfe {

    // normalisiere(text: Zeichenkette): Zeichenkette
    // Grossbuchstaben bleiben, Kleinbuchstaben werden gross, ae/oe/ue/ss
    // fuer Umlaute und Eszett, alle anderen Zeichen fallen weg.
    // Beispiel: "Grüße an Bob!" -> "GRUESSEANBOB"
    public static String normalisiere(String text) {
        String s = "";
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            int a = (int) c;
            if (a >= 65 && a <= 90) {
                s = s + c;
            } else if (a >= 97 && a <= 122) {
                s = s + (char) (a - 32);
            } else if (a == 228 || a == 196) {
                s = s + "AE";
            } else if (a == 246 || a == 214) {
                s = s + "OE";
            } else if (a == 252 || a == 220) {
                s = s + "UE";
            } else if (a == 223) {
                s = s + "SS";
            }
        }
        return s;
    }

    // mod(a: Ganzzahl, m: Ganzzahl): Ganzzahl
    // kleinster nicht negativer Rest (wie mod in der Abitur-Anlage),
    // z. B. mod(-3, 26) = 23. Achtung: In Java ergibt -3 % 26 = -3!
    public static int mod(int a, int m) {
        int r = a % m;
        if (r < 0) {
            r = r + m;
        }
        return r;
    }

    // wert(c: Zeichen): Ganzzahl
    // Buchstabenwert mit A = 0 ... Z = 25 (ASCII-Wert minus 65).
    // ACHTUNG Falle P1: Auf Papier gilt A = 1 ... Z = 26!
    public static int wert(char c) {
        return (int) c - 65;
    }

    // zeichen(w: Ganzzahl): Zeichen
    // Buchstabe zum Wert w (A = 0); w wird vorher modulo 26 genommen.
    public static char zeichen(int w) {
        return (char) (mod(w, 26) + 65);
    }

    // hex2(n: Ganzzahl): Zeichenkette
    // Zahl von 0 bis 255 als zwei Hexadezimalziffern, z. B. 7 -> "07",
    // 26 -> "1A", 255 -> "FF".
    public static String hex2(int n) {
        String ziffern = "0123456789ABCDEF";
        return "" + ziffern.charAt(n / 16) + ziffern.charAt(n % 16);
    }

    // hexWert(c: Zeichen): Ganzzahl
    // Wert einer Hexadezimalziffer '0'...'9', 'A'...'F' (0 bis 15).
    public static int hexWert(char c) {
        int a = (int) c;
        if (a >= 48 && a <= 57) {
            return a - 48;
        }
        return a - 55;
    }
}


